// module config
function mixpay_config(){
    global $aInt;
    global $_ADDONLANG;
    $addonlang = $_ADDONLANG;
    $module = "mixpay";
    $addonlangfile = ROOTDIR . "/modules/addons/" . $module . "/lang/" . $aInt->language . ".php";  // load language file
    if (file_exists($addonlangfile)) {
        require $addonlangfile;
    }
 
    $_ADDONLANG = array_merge($addonlang, $_ADDONLANG);

    $configarray = array(
        "name" => 'MixPay '.$_ADDONLANG["transactions"],
	    "description" => $_ADDONLANG["transactionsDescription"],
        'author' => 'Netsto.com',
	    "version" => "1.0",
        "language" => "chinese"
    );
    return $configarray;
}

//create table
function mixpay_activate() {
    mysql_query("CREATE TABLE `mixpay_orders` (
		`id` int(11) NOT NULL AUTO_INCREMENT,
		`userId` int(11) NOT NULL COMMENT 'User ID',
		`InvoiceId` varchar(255) NOT NULL COMMENT 'Invoice ID',
		`orderId` varchar(255) NOT NULL COMMENT 'Order ID',
		`payeeId` varchar(255) DEFAULT NULL COMMENT 'payeeId',
		`settlementAssetId` varchar(255) NULL DEFAULT NULL COMMENT 'settlementAssetId',
		`quoteAssetId` varchar(255) NULL DEFAULT NULL COMMENT 'quoteAssetId',
		`amount` varchar(255) COLLATE utf8_unicode_ci NOT NULL COMMENT 'Amount',
		`ActualAmount` varchar(255) COLLATE utf8_unicode_ci NOT NULL COMMENT 'Actual Amount',
        `quoteSymbol` varchar(255) NULL DEFAULT NULL COMMENT 'Quote Symbol',
		`status` varchar(255) NOT NULL DEFAULT 'Unpaid' COMMENT 'Payment Status',
		`time` datetime NULL DEFAULT NULL COMMENT 'Payment Time',
        `remarks` text NULL DEFAULT NULL COMMENT 'Remarks',
		`created_at` datetime NULL DEFAULT NULL COMMENT 'Created Time',
		`updated_at` datetime NULL DEFAULT NULL COMMENT 'Updated Time',
		PRIMARY KEY (`id`)
	) ENGINE=InnoDB DEFAULT CHARSET=utf8;");
}

